var e={"feedback.title":`发送反馈`,"feedback.description":`遇到 bug、有想法或有不清楚的地方？你的 Harness 会先看看自己能否回答或直接处理。如果不能，消息会发送给 Harness Maxxing 团队，我们会阅读每一条消息。`,"feedback.checking":`你的 Harness 正在阅读你的消息…`,"feedback.reply.answerTitle":`你的 Harness 有答案`,"feedback.reply.selfTitle":`你的 Harness 可以在这里完成`,"feedback.reply.notSent":`没有向团队发送任何内容。`,"feedback.reply.prompt":`查看为会话准备的请求`,"feedback.reply.open":`打开会话`,"feedback.reply.edit":`编辑我的消息`,"feedback.reply.force":`仍然发送给团队`,"feedback.type.bug":`Bug`,"feedback.type.idea":`想法`,"feedback.type.other":`其他`,"feedback.message":`消息`,"feedback.placeholder.bug":`发生了什么、你期望的结果，以及如何复现…`,"feedback.placeholder.idea":`你希望 Harness Maxxing 做什么？`,"feedback.placeholder.other":`你的消息…`,"feedback.email":`你的邮箱`,"feedback.emailHint":`必填，以便我们回复你（也用于防止滥用）。不会用于其他用途。`,"feedback.send":`发送`,"feedback.sentWith":`已随版本（{version}）发送`,"feedback.sentWithName":`已随版本（{version}）和你的昵称（{name}）发送`,"feedback.sentTitle":`谢谢！`,"feedback.sentBody":`你的消息已送达团队。确认邮件将发送至 {email}。`,"feedback.err.email":`请输入有效的邮箱地址`,"feedback.err.message":`请写几句话`,"feedback.err.rate":`消息过多，请稍后再试。`,"feedback.err.unreachable":`此服务器目前无法联系到 Harness Maxxing 团队，请稍后再试。`,"feedback.zone":`截取区域`,"feedback.zoneBlur":`隐藏我的数据（演示模式）`,"feedback.zoneHint":`拖动选择要发送的屏幕区域 · Enter = 整个屏幕 · Esc = 取消`,"feedback.zoneHintTouch":`拖动选择要发送的屏幕区域`,"feedback.zoneWhole":`整个屏幕`,"feedback.zoneTaking":`正在截图…`,"feedback.zoneAlt":`随消息发送的截图`,"feedback.zoneRedo":`重新截图`,"feedback.zoneRemove":`移除`,"feedback.zoneFailed":`无法截图，请尝试更小的区域。`,"feedback.err.image":`截图被拒绝。请移除它或截取更小的区域。`,"feedback.err.offline":`此服务器已设置为从不连接 Harness Maxxing 云端。`};export{e as default};